360: async function runQuickCalibration(): Promise<Record<Line, Stage>> {
361:   const altitudes: Partial<Record<Line, Stage>> = {};
362:   const lines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
363: 
364:   banner('Quick Calibration');
365:   console.log(`  ${chalk.dim('A brief probe of each developmental line to set your starting altitudes.')}\n`);
366: 
367:   for (const line of lines) {
368:     let stage: Stage = 'Red';
369:     let confidence = 0.5;
370:     let trial: TrialResult;
371: 
372:     if (line === 'Somatic' || line === 'Willpower') {
373:       // ── Hold probe: measure timing accuracy ──
374:       const target = HOLD_TARGETS[line]!;
375:       const targetSec = (target / 1000).toFixed(1);
376: 
377:       console.log(`  ${chalk.bold.cyan(line + ':')} ${chalk.dim('Timing probe')}`);
378:       console.log(`  ${chalk.dim('Press Enter when you think ' + targetSec + ' seconds have passed.')}\n`);
379: 
380:       const startTime = Date.now();
381:       const answer = await clackText({ message: `Press Enter after ~${targetSec}s...`, defaultValue: '' });
382:       if (typeof answer === 'symbol') { altitudes[line] = 'Red'; continue; }
383:       const elapsed = Date.now() - startTime;
384: 
385:       const accuracy = Math.max(0, 1 - Math.abs(elapsed - target) / target);
386: 
387:       let threshold: number;
388:       if (line === 'Somatic') {
389:         // Inverted: lower RT = higher stage (range 200-900)
390:         threshold = 900 - accuracy * 700;
391:       } else {
392:         // Standard: higher = better (range 1-12)
393:         threshold = 1 + accuracy * 11;
394:       }
395: 
396:       stage = thresholdToStage(line, threshold);
397: 
398:       trial = {
399:         taskId: `cal-${line.toLowerCase()}`,
400:         timestamp: Date.now(),
401:         dimensions: { accuracy, response_time: accuracy },
402:         rawResponse: elapsed,
403:         durationMs: elapsed,
404:       };
405: 
406:       confidence = computeConfidence([trial], 0.5);
407: 
408:     } else {
409:       // ── LLM dialogue probe: multiple choice ──
410:       const probe = CALIBRATION_PROMPTS[line];
411:       if (!probe) { altitudes[line] = 'Red'; continue; }
412: 
413:       console.log(`  ${chalk.bold.cyan(line + ':')}`);
414:       console.log(`  ${chalk.dim(probe.prompt)}\n`);
415: 
416:       const choice = await select({
417:         message: `How would you approach this?`,
418:         options: probe.options.map((opt) => ({ value: opt, label: opt })),
419:       });
420: 
421:       if (typeof choice === 'symbol') { altitudes[line] = 'Red'; continue; }
422: 
423:       const choiceIdx = probe.options.indexOf(choice as string);
424:       const idx = choiceIdx >= 0 ? choiceIdx : 0;
425: 
426:       const thresholds = CHOICE_THRESHOLDS[line]!;
427:       const threshold = thresholds[Math.min(idx, 2)];
428: 
429:       stage = thresholdToStage(line, threshold);
430: 
431:       const depthScores = [0.3, 0.6, 0.85];
432:       const coherenceScores = [0.4, 0.7, 0.9];
433: 
434:       trial = {
435:         taskId: `cal-${line.toLowerCase()}`,
436:         timestamp: Date.now(),
437:         dimensions: { depth: depthScores[idx], coherence: coherenceScores[idx] },
438:         rawResponse: idx,
439:         durationMs: 0,
440:       };
441: 
442:       confidence = computeConfidence([trial], 0.5);
443:     }
444: 
445:     altitudes[line] = stage;
446: 
447:     const stageIdx = CAL_STAGES.indexOf(stage as typeof CAL_STAGES[number]);
448:     const color = stageColor(stage);
449:     const bar = '■'.repeat(stageIdx + 1) + '○'.repeat(7 - stageIdx);
450:     console.log(`  ${line.padEnd(14)} ${bar} ${color(stage)} ${chalk.dim('(confidence: ' + confidence.toFixed(2) + ')')}\n`);
451:   }
452: 
453:   console.log(`\n  ${chalk.bold('Calibration complete:')}`);
454:   for (const line of lines) {
455:     const s = altitudes[line] ?? 'Red';
456:     const color = stageColor(s);
457:     console.log(`    ${line.padEnd(14)} ${color(s)}`);
458:   }
459:   console.log('');
460: 
461:   return altitudes as Record<Line, Stage>;
462: }
