559: /** Render an altitude bar chart showing per-line stage progression */
560: function renderAltitudesChart(sig: Significator): void {
561:   const orderedLines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
562:   const allStages = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'] as const;
563:   const stageKeys: readonly string[] = allStages;
564: 
565:   for (const line of orderedLines) {
566:     const current = sig.altitudes[line] ?? 'Red';
567:     const currentIdx = stageKeys.indexOf(current);
568:     const color = stageColor(current);
569: 
570:     // Build a horizontal bar: filled squares up to current stage, empty beyond
571:     const bars = stageKeys.map((s, i) => {
572:       if (i < currentIdx) return chalk.dim('■');  // passed stages
573:       if (i === currentIdx) return color('●'); // current stage
574:       return chalk.dim('○'); // future stages
575:     });
576: 
577:     // Segment label: first 3 stages, current, last 2
578:     const segLabels = stageKeys.map((s, i) => {
579:       if (i === 0 || i === stageKeys.length - 1 || i === currentIdx) {
580:         return i === currentIdx ? color(stageAbbr(s)) : chalk.dim(stageAbbr(s));
581:       }
582:       return '  '; // skip most labels for compactness
583:     });
584: 
585:     // Pad line name to 15 chars for alignment
586:     const paddedLine = line.padEnd(14);
587:     if (!JSON_MODE) {
588:       console.log(`  ${paddedLine} ${bars.join('')} ${chalk.dim(current)}`);
589:     }
590:   }
591: }
