252:   /**
253:    * Build a narrative continuity context from the last 3 encounters.
254:    * Injected into both LLM system prompt and fallback task framing.
255:    */
256:   private buildContinuityContext(): string {
257:     if (this.history.length === 0) return '';
258:     const recent = this.history.slice(-3);
259:     const lines = recent.map((r, i) => {
260:       const passed = Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced');
261:       const shadow = r.shadowSurfaced ? ` Shadow surfaced: ${r.shadowSurfaced}.` : '';
262:       const altShift = r.altitudeShift ? ` LINE ADVANCED: ${r.altitudeShift.line} ${r.altitudeShift.from}→${r.altitudeShift.to}.` : '';
263:       const polarity = r.polarityTrace.energeticDirection === 'Radiative' ? ' (STO/radiative)' : r.polarityTrace.energeticDirection === 'Absorptive' ? ' (STS/absorptive)' : '';
264:       const moduleRef = r.encounterId.split(':')[0] ?? '';
265:       return `  ${i + 1}. [${moduleRef}] ${passed ? '✓ PASSED' : '✗ FAILED'}${polarity} — ${r.narrativeSummary.slice(0, 150)}${shadow}${altShift}`;
266:     });
267:     return `\n[RECENT JOURNEY — the player's developmental arc. Build upon these encounters. Reference specific events from them. The player remembers what happened.]\n${lines.join('\n')}`;
268:   }
