589:       polarityDirection: 'neutral' as const,
590:       narrativeSummary: `The player engaged in deep reflection on ${this.encounter.moduleRef}.`,
591:     };
592:     const finalResult = this.createAssessmentResult(true, {});
593:     const outcome = this.finalizeEncounter(fallbackParams, now);
