602:   /**
603:    * Fallback mode: use module content when available, FallbackProvider otherwise.
604:    * When a module is available, presents real assessment tasks (n-back, dilemmas,
605:    * emotion identification, etc.) as narrative challenges and evaluates responses
606:    * using the module's drive probes. Also detects shadow patterns and computes
607:    * altitude shifts from consistent healthy patterns.
608:    */
609:   private async runFallback(line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
610:     // CHECK: If we have an assessment module, use it for a real assessment
611:     if (this.module) {
612:       return this.runModuleAssessment(line, stage, now);
613:     }
614: 
615:     // Original generic fallback when no module is available
616:     const fallback = getFallback(this.encounter.modality, line, stage);
617:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
618:     const holonName = holon?.name ?? 'A presence';
619:     const holonRole = holon?.narrativeRole ?? 'guide';
620:     const encounterModality = this.encounter.modality;
621: 
622:     let narrativeIntro: string;
623:     let questionText: string;
624:     let options: { label: string; description: string }[] = [];
625: 
626:     switch (encounterModality) {
627:       case 'LanguageReflective':
628:         narrativeIntro = `${holonName} sits across from you, their gaze steady. The firelight casts long shadows. They speak:`;
629:         questionText = fallback.prompt ?? 'What moved you to act?';
630:         options = [
631:           { label: 'Reflect deeply', description: 'Consider the question from multiple angles' },
632:           { label: 'Respond instinctively', description: 'Trust your first impulse' },
633:           { label: 'Sit with it', description: 'Allow the question to remain open' },
634:           { label: 'Challenge the premise', description: 'Question the foundation of what was asked' },
635:         ];
636:         break;
637:       case 'ScenarioChoice':
638:         narrativeIntro = `${holonName} confronts you. The air is tense. A choice must be made.`;
639:         questionText = fallback.scenario ?? 'A crossroads appears. Each path carries weight.';
640:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
641:         break;
642:       case 'Strategic':
643:         narrativeIntro = `The war-table is spread before you. ${holonName} surveys the terrain. Three routes. Limited forces.`;
644:         questionText = fallback.scenario ?? fallback.prompt ?? 'Resources are limited. The map shows three routes to the objective.';
645:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
646:         break;
647:       case 'Embodied':
648:         narrativeIntro = `The war-drums begin. ${holonName} guides you. Your body knows this rhythm.`;
649:         questionText = fallback.prompt ?? 'Close your eyes. Where do you feel tension in your body right now?';
650:         options = [
651:           { label: 'Follow the rhythm', description: 'Let the drum guide your body' },
652:           { label: 'Resist the beat', description: 'Fight against the pull' },
653:           { label: 'Breathe into it', description: 'Allow the sensation to move through you' },
654:           { label: 'Still yourself', description: 'Find the stillness within the movement' },
655:         ];
656:         break;
657:       case 'SocialCooperative':
658:         narrativeIntro = `${holonName} looks to you. Others wait for direction. The group needs your word.`;
659:         questionText = fallback.scenario ?? 'The scouts look to you. The path splits — one leads through danger, the other through uncertainty.';
660:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
661:         break;
662:       case 'ImmersiveRPG':
663:         narrativeIntro = `The world stretches before you. ${holonName} appears — ${holonRole} of this domain. What calls?`;
664:         questionText = fallback.prompt ?? 'The world stretches before you. A path winds through unfamiliar terrain. Something waits ahead.';
665:         options = [
666:           { label: 'Press forward', description: 'Step into the unknown' },
667:           { label: 'Survey the area', description: 'Gather information first' },
668:           { label: 'Seek shelter', description: 'Find safety before advancing' },
669:           { label: 'Call out', description: 'Announce your presence' },
670:         ];
671:         break;
672:       default:
673:         narrativeIntro = `${holonName} presents a challenge. The moment demands clarity.`;
674:         questionText = fallback.prompt ?? fallback.framing ?? 'Focus. The moment demands clarity.';
675:         options = [
676:           { label: 'Engage', description: 'Step into the challenge' },
677:           { label: 'Reflect', description: 'Consider before acting' },
678:           { label: 'Withdraw', description: 'Step back and reassess' },
679:           { label: 'Negotiate', description: 'Seek a middle path forward' },
680:         ];
681:         break;
682:     }
683: 
684:     const defaultOpts = [
685:       { label: 'Act decisively', description: 'Take the direct approach' },
686:       { label: 'Observe first', description: 'Gather more information' },
687:       { label: 'Seek alliance', description: 'Find strength in others' },
688:       { label: 'Deceive and maneuver', description: 'Use misdirection to your advantage' },
689:     ];
690:     while (options.length < 4) {
691:       const extra = defaultOpts[options.length];
692:       if (extra) options.push(extra);
693:       else break;
694:     }
695: 
696:     const fullPrompt = `${narrativeIntro}\n\n${questionText}`;
697: 
698:     const askParams: AskUserQuestionParams = {
699:       questions: [{
700:         question: fullPrompt,
701:         header: encounterModality,
702:         options,
703:         allowWriteIn: true,
704:         multiSelect: false,
705:       }],
706:     };
707: 
708:     const result = await this.uiHandler.askUser(askParams);
709:     const answer = result.answers[0];
710:     const narrativeSummary = answer?.writeInValue ?? (answer?.selectedLabels[0] ?? 'The player engaged with the encounter.');
711: 
712:     const evaluated = this.evaluateFallbackResponse(narrativeSummary);
713: 
714:     const fallbackParams = {
715:       passed: evaluated.passed,
716:       feedback: evaluated.feedback,
717:       polarityDirection: evaluated.polarityDirection,
718:       driveScores: evaluated.driveScores,
719:       driveSignals: evaluated.driveSignals,
720:       narrativeSummary: typeof narrativeSummary === 'string' ? narrativeSummary : 'The player engaged with the encounter.',
721:     };
722: 
723:     const finalResult = this.createAssessmentResult(evaluated.passed, {}, evaluated.driveScores);
724:     const outcome = this.finalizeEncounter(fallbackParams, now);
725: 
726:     return {
727:       ...outcome,
728:       finalResult,
729:       messages: this.messages,
730:     };
731:   }
