733:   /**
734:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
735:    * and scoring rubric to present a real developmental assessment even without the LLM.
736:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
737:    * evaluates the response against drive probes, detects shadow patterns,
738:    * and computes altitude progression.
739:    */
740:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
741:     const module = this.module!;
742:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
743:     const holonName = holon?.name ?? 'A presence';
744:     const currentModality = this.encounter.modality;
745: 
746:     // 1. Select the best task from the module based on modality
747:     const task = this.selectTaskForModality(module, currentModality);
748:     // Track the actual presented task for narrative building (fix B.2)
749:     this._currentPresentedTask = task;
750: 
751:     // 2. Present the task as a narrative challenge via uiHandler
752:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
753:     const answer = askResult.answers[0];
754:     const rawLabel = answer?.selectedLabels[0] ?? '';
755:     const writeIn = answer?.writeInValue;
756:     const playerResponseText = writeIn ?? rawLabel;
757: 
758:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
759:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
760:     const endTimeMs = Date.now();
761:     let evaluation: {
762:       passed: boolean;
763:       polarityDirection: 'sto' | 'sts' | 'neutral';
764:       driveScores: { agency: number; communion: number; eros: number; agape: number };
765:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
766:       feedback: string;
767:     };
768:     let trialResult: TrialResult | null = null;
769: 
770:     if (this._currentRendererEvaluate) {
771:       // Use the TaskRenderer's evaluate function for real scoring
772:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
773: 
774:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
775:       const rawResp = trialResult?.rawResponse as any;
776:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
777:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
778:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
779: 
780:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
781:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
782: 
783:       // D.9: Use shared shadow keyword detection helper (DRY)
784:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
785:       if (writeIn) {
786:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
787:       }
788: 
789:       // When a write-in is present, its keyword-based detection takes priority over
790:       // the renderer's label matching (which can false-positive on short words like 'I').
791:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
792:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
793: 
794:       // Build differentiated drive scores:
795:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
796:       // - Other drives get baseline neutral (0.5)
797:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
798:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
799: 
800:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
801:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
802:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
803:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
804:       const rubricWeights = module.scoringRubric.dimensionWeights;
805:       const trialDims = trialResult!.dimensions;
806:       let weightedSum = 0;
807:       let totalWeight = 0;
808:       for (const [dim, weight] of Object.entries(rubricWeights)) {
809:         const val = trialDims[dim as keyof typeof trialDims];
810:         if (weight && typeof val === 'number') {
811:           weightedSum += val * weight;
812:           totalWeight += weight;
813:         }
814:       }
815:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
816:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
817:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
818: 
819:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
820:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
821:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
822:       const driveScores = {
823:         agency: effectiveDrive === 'agency' ? matchedScore
824:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
825:           : matchedScore,
826:         communion: effectiveDrive === 'communion' ? matchedScore
827:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
828:           : matchedScore,
829:         eros: effectiveDrive === 'eros' ? matchedScore
830:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
831:           : matchedScore,
832:         agape: effectiveDrive === 'agape' ? matchedScore
833:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
834:           : matchedScore,
835:       };
836: 
837:       // Determine polarity from the effective drive detection
838:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
839:         : effectivePolarity === 'sto' ? 'sto' as const
840:         : 'neutral' as const;
841: 
842:       // Derive drive signals from the expression pattern.
843:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
844:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
845:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
846:       const driveSignals = {
847:         agency: effectiveDrive === 'agency'
848:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
849:           : 'HealthyBalanced',
850:         communion: effectiveDrive === 'communion'
851:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
852:           : 'HealthyBalanced',
853:         eros: effectiveDrive === 'eros'
854:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
855:           : 'HealthyBalanced',
856:         agape: effectiveDrive === 'agape'
857:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
858:           : 'HealthyBalanced',
859:       };
860: 
861:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
862:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
863:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
864:       const hasShadow = !!shadowFromWriteIn;
865:       const passed = !hasShadow && effectiveScore >= passThreshold;
866: 
867:       // Build contextual developmental feedback based on score, drive, polarity, and history
868:       const driveLabel = effectiveDrive ?? 'unidentified';
869:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
870:       const scorePct = (baseScore * 100).toFixed(0);
871:       const historyCount = this.history.length;
872:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
873:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
874:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
875:         : '';
876: 
877:       const feedback = hasShadow
878:         ? `A ${shadowFromWriteIn} pattern surfaced through your ${driveLabel} expression (${polarityLabel}). In the developmental framework, this shadow arises when the ${driveLabel} drive becomes imbalanced — either clinging to lower patterns (dark) or bypassing toward higher without integration (golden). Naming it here is the first step toward healing it. ${historyCount > 0 ? `This is your ${historyCount + 1}th encounter — each shadow surfaced is an opportunity for the field to work with you.` : ''}`
879:         : passed
880:           ? `Your ${driveLabel} drive expressed with health (performance: ${scorePct}%, polarity: ${polarityLabel}). ${parseInt(scorePct) >= 80 ? 'Strong performance — the integration is deepening across the ' + module.line.toLowerCase() + ' dimension.' : 'Solid engagement — the ' + module.line.toLowerCase() + ' capacity at ' + module.stage + ' stage is growing.'} ${consistencyNote}The field recognizes your sustained attention to this developmental edge.`
881:           : `Your ${driveLabel} drive expressed at ${scorePct}% performance (${polarityLabel}). ${parseInt(scorePct) >= 40 ? 'Close to the threshold — the gap between where you are and where this capacity can be is narrowing. A focused effort on the next encounter may tip the balance.' : 'This is a genuine edge for you. The ' + module.line.toLowerCase() + ' line at ' + module.stage + ' stage is where your developmental work lives right now — not as punishment, but as invitation.'} The ${module.line.toLowerCase()} dimension will continue to offer opportunities to strengthen this capacity.`;
882: 
883:       evaluation = {
884:         passed,
885:         polarityDirection,
886:         driveScores,
887:         driveSignals,
888:         feedback,
889:       };
890:     } else {
891:       // Fallback: keyword-based evaluation
892:       evaluation = this.evaluateViaDriveProbes(module, playerResponseText);
893:     }
894: 
895:     // 4. Detect shadow surfacing from response pattern (with optional forceShadow override)
896:     const validQuadrants = ['DarkAddiction', 'DarkAllergy', 'GoldenAddiction', 'GoldenAllergy'] as const;
897:     const forcedQuadrant = this.forceShadow && validQuadrants.includes(this.forceShadow as any)
898:       ? this.forceShadow as ShadowQuadrant
899:       : null;
900:     // Shadow detection only fires for write-in text (free-form responses)
901:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
902:     const isWriteIn = !!writeIn;
903:     const shadowSignal = forcedQuadrant
904:       ? { quadrant: forcedQuadrant, intensity: 0.7 }
905:       : this.detectShadowFromResponse(playerResponseText, currentModality, isWriteIn);
906: 
907:     // G.25: Wire ShadowDetector — detect behavioral shadows from encounter patterns
908:     const { detectShadows, computeBehavioralPatterns } = await import('../usecases/ShadowDetector.js');
909:     const recentEncounters = this.significator.recentEncounters.slice(-20);
