1036:     const activeEvents = (updated.world as any).activeMacroEvents ?? [];
1037:     const macroEvent = tryTriggerMacroEvent(newTension, activeEvents, finalSig.currentStage, now);
1038:     const newActiveEvents = macroEvent ? [...activeEvents, macroEvent] : activeEvents;
1039:     const updatedWorld = { ...updated.world, pestleTension: newTension, activeMacroEvents: newActiveEvents } as WorldState;
1040: 
1041:     return {
1042:       updatedSig: finalSig,
1043:       updatedWorld,
1044:       finalResult,
1045:       consequenceRecord: updatedRecord,
1046:       narrativeSummary,
1047:       feedback: evaluation.feedback,
1048:       messages: this.messages,
1049:     };
1050:   }
