1052:   /**
1053:    * Select the best assessment task from the module based on encounter modality.
1054:    */
1055:   private selectTaskForModality(module: StageAssessment, modality: Modality): AssessmentTask {
1056:     // All task types supported by TaskRenderers
1057:     const ALL_RENDERABLE: readonly TaskType[] = [
1058:       'n_back', 'stroop', 'go_no_go', 'hold', 'pattern_prediction',
1059:       'emotion_identification', 'dilemma', 'scenario', 'self_report',
1060:       'value_ranking', 'reaction_time', 'rhythm', 'cooperation', 'imitation',
1061:     ];
1062: 
1063:     // Modality-specific preference order (first match wins)
1064:     const modalityPreference: Record<string, readonly TaskType[]> = {
1065:       Deterministic: ['n_back', 'stroop', 'go_no_go', 'hold', 'reaction_time', 'rhythm', 'pattern_prediction'],
1066:       LanguageReflective: ['llm_dialogue', 'self_report', 'emotion_identification', 'scenario', 'dilemma'],
1067:       ScenarioChoice: ['dilemma', 'scenario', 'emotion_identification', 'self_report'],
1068:       Embodied: ['hold', 'rhythm', 'imitation', 'reaction_time', 'go_no_go'],
1069:       Strategic: ['pattern_prediction', 'value_ranking', 'n_back', 'stroop'],
1070:       SocialCooperative: ['cooperation', 'dilemma', 'emotion_identification', 'scenario', 'self_report'],
1071:       ImmersiveRPG: ['scenario', 'dilemma', 'llm_dialogue', 'emotion_identification', 'self_report'],
1072:     };
1073: 
1074:     const preferred = modalityPreference[modality] ?? ALL_RENDERABLE;
1075: 
1076:     // G.1: Try preferred types first, then fall back to any renderable type in the module
1077:     for (const prefType of [...preferred, ...ALL_RENDERABLE]) {
1078:       const match = module.tasks.find(t => t.type === prefType);
1079:       if (match) return match;
1080:     }
1081: 
1082:     // Last resort: generate a modality-appropriate task
1083:     return this.generateModalityFallbackTask(modality, module);
1084:   }
