1086:   /**
1087:    * Generate a generic task appropriate for the modality when the module
1088:    * doesn't have any of the preferred task types. This ensures ScenarioChoice
1089:    * always shows a dilemma, ImmersiveRPG always shows a scenario, etc.
1090:    */
1091:   private generateModalityFallbackTask(modality: Modality, module: StageAssessment): AssessmentTask {
1092:     const prefix = `${module.line.toLowerCase()}-${module.stage.toLowerCase()}`;
1093:     // Inject stage into all generated task parameters so TaskRenderers can use it for difficulty scaling
1094:     const stage = module.stage;
1095:     switch (modality) {
1096:       case 'ScenarioChoice':
1097:       case 'ImmersiveRPG':
1098:         return {
1099:           id: `generic-dilemma-${prefix}`,
1100:           type: 'dilemma',
1101:           description: `A developmental dilemma at the ${module.stage} stage of ${module.line} development`,
1102:           parameters: { dilemmaType: 'developmental', choices: 4, stage, line: module.line },
1103:           measures: ['depth', 'coherence'],
1104:         };
1105:       case 'LanguageReflective':
1106:         return {
1107:           id: `generic-self-report-${prefix}`,
1108:           type: 'self_report',
1109:           description: `Self-inquiry reflection at the ${module.stage} stage of ${module.line} development`,
1110:           parameters: { stage },
1111:           measures: ['depth', 'metacognition'],
1112:         };
1113:       case 'SocialCooperative':
1114:         return {
1115:           id: `generic-cooperation-${prefix}`,
1116:           type: 'cooperation',
1117:           description: `Cooperative dynamics at the ${module.stage} stage of ${module.line} development`,
1118:           parameters: { stage },
1119:           measures: ['depth', 'coherence'],
1120:         };
1121:       case 'Embodied':
1122:         return {
1123:           id: `generic-hold-${prefix}`,
1124:           type: 'hold',
1125:           description: `Attentional hold at the ${module.stage} stage of ${module.line} development`,
1126:           parameters: { items: 3, holdDurationMs: 5000, stage },
1127:           measures: ['accuracy', 'consistency'],
1128:         };
1129:       case 'Strategic':
1130:         return {
1131:           id: `generic-pattern-${prefix}`,
1132:           type: 'pattern_prediction',
1133:           description: `Pattern recognition at the ${module.stage} stage of ${module.line} development`,
1134:           parameters: { disks: 3, attempts: 4, stage },
1135:           measures: ['accuracy', 'complexity_handled'],
1136:         };
1137:       case 'Deterministic':
1138:       default:
1139:         return module.tasks[0] ?? {
1140:           id: `generic-nback-${prefix}`,
1141:           type: 'n_back',
1142:           description: `Working memory challenge at the ${module.stage} stage of ${module.line} development`,
1143:           parameters: { n: 2, trials: 12, stage },
1144:           measures: ['accuracy', 'response_time'],
1145:         };
1146:     }
1147:   }
