1320:   /**
1321:    * Detect shadow surfacing from response patterns.
1322:    * Uses keyword heuristics aligned with the 4-quadrant shadow model.
1323:    */
1324:   private detectShadowFromResponse(
1325:     responseText: string,
1326:     _modality: Modality,
1327:     isWriteIn: boolean = false,
1328:   ): { quadrant: ShadowQuadrant; intensity: number } | null {
1329:     // Shadow detection only fires for write-in text (free-form responses)
1330:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
