1478:   private evaluateFallbackResponse(selectedLabel: string): {
1479:     passed: boolean;
1480:     polarityDirection: 'sto' | 'sts' | 'neutral';
1481:     driveScores: { agency: number; communion: number; eros: number; agape: number };
1482:     driveSignals: { agency: string; communion: string; eros: string; agape: string };
1483:     feedback: string;
1484:   } {
1485:     const lower = selectedLabel.toLowerCase();
1486:     
1487:     // Check passed first (false if contains withdraw, resist, decline, sit with it)
1488:     const passed = !['withdraw', 'resist', 'decline', 'sit with it'].some(kw => lower.includes(kw));
1489: 
1490:     const defaultSignals = {
1491:       agency: 'HealthyBalanced',
1492:       communion: 'HealthyBalanced',
1493:       eros: 'HealthyBalanced',
1494:       agape: 'HealthyBalanced'
1495:     };
1496: 
1497:     // 1. STS mapping
1498:     const stsKeywords = ['attack', 'betray', 'raid', 'dominate', 'strike', 'profit', 'sell', 'enforce', 'deceive', 'obey'];
1499:     if (stsKeywords.some(kw => lower.includes(kw))) {
1500:       const isAverted = ['betray', 'raid', 'deceive'].some(kw => lower.includes(kw));
