1266:           if (v === 'HealthyBalanced') return `${chalk.dim(k.slice(0, 3) + ':')}${chalk.green('ok')}`;
1267:           const col = v.startsWith('Dark') ? chalk.red : chalk.yellow;
1268:           return `${col(k.slice(0, 3) + ':' + (SHADOW_LABELS[v] ?? v.slice(0, 5)))}`;
1269:         });
1270:         console.log(`  ${chalk.dim('drives:')} ${allDriveEntries.join(' ')}  ${chalk.dim(polarityIcon + cr.polarityTrace.stageOrientation)}`);
1271:         // Show shadow status
1272:         const shadow = result.outcome.consequenceRecord.shadowSurfaced;
1273:         if (shadow) {
1274:           console.log(`  ${chalk.yellow('⚠ shadow:')} ${chalk.yellow(shadow)}`);
1275:         }
1276:       }
1277: 
1278:       if (VERBOSE) {
1279:         verbose('feedback', result.outcome.feedback.slice(0, 200));
1280:         verbose('updatedEncounters', String(currentSig.totalEncounters));
1281:       }
1282: 
1283:       emitEvent('encounter_completed', {
1284:         encounter: selectedEncounter.id,
1285:         modality: selectedEncounter.modality,
1286:         module: selectedEncounter.moduleRef,
1287:         passed: result.outcome.finalResult.passed,
1288:         narrative: result.narrativeSummary,
1289:         totalEncounters: currentSig.totalEncounters,
1290:       });
1291: 
1292:       completedCount++;
1293:       if (result.outcome.finalResult.passed) passedCount++;
1294:     } catch (err: any) {
1295:       error(`Encounter failed: ${err.message || err}`);
1296:       emitEvent('encounter_error', { encounter: selectedEncounter.id, error: err.message });
1297:     }
1298: 
1299:       // Check transformation
1300:     if (tickResult.transformation) {
1301:       if (!JSON_MODE) console.log(`\n  ${chalk.magenta('⚡ TRANSFORMATION: ' + tickResult.transformation.targetStage)}`);
1302:       emitEvent('transformation', { targetStage: tickResult.transformation.targetStage, readiness: tickResult.transformation.readiness });
1303:     }
1304: 
1305:     if (!JSON_MODE && tickResult.bleedThrough.length > 0) {
1306:       console.log(`  ${chalk.dim('layers:')} ${renderLayersCompact(currentSig, tickResult.bleedThrough)}`);
1307:     }
1308: 
1309:   }
1310: 
1311:   // Session end — apply theta-decay and persist
1312:   const sessionEnd = endSession(currentSig, sessionState, now + encounterCount * 5000);
1313: 
1314:   // Save progress to disk (Significator + WorldState)
1315:   saveGame(sessionEnd.sig);
1316:   saveWorldState(currentWorld);
1317:   if (!JSON_MODE) info('save', `${chalk.green('Progress saved')}`);
1318: 
1319:   banner('SESSION END');
1320: 
1321:   // Session closure narrative
1322:   if (!JSON_MODE) {
1323:     // passedCount tracked directly from encResult.passed during the loop
1324:     const failedCount = completedCount - passedCount;
1325:     const shadowsSurfaced = sessionEnd.summary.shadowsSurfaced;
1326:     const altShifts = history.filter(r => r.altitudeShift !== null).length;
1327: 
1328:     // Rich thematic closure that references what happened
1329:     const linesAdvanced = history.filter(r => r.altitudeShift !== null).map(r => r.altitudeShift!.line);
1330:     const uniqueLinesAdvanced = [...new Set(linesAdvanced)];
1331:     const shadowsByQuadrant: Record<string, number> = {};
1332:     for (const r of history) {
1333:       if (r.shadowSurfaced) {
1334:         shadowsByQuadrant[r.shadowSurfaced] = (shadowsByQuadrant[r.shadowSurfaced] ?? 0) + 1;
1335:       }
1336:     }
1337:     const shadowDetail = Object.entries(shadowsByQuadrant).map(([q, n]) => `${n}×${q}`).join(', ');
1338: 
1339:     const openingLine = passedCount > failedCount
1340:       ? `${chalk.green('This session favored integration.')} ${passedCount}/${completedCount} encounters met their developmental threshold.`
1341:       : `${chalk.yellow('This session was heavy with unfinished catalyst.')} ${failedCount}/${completedCount} encounters remain un-integrated.`;
1342: 
1343:     const altLine = uniqueLinesAdvanced.length > 0
1344:       ? `  ${chalk.magenta('⚡ Lines advanced: ' + uniqueLinesAdvanced.join(', '))}`
1345:       : '';
1346: 
1347:     const shadowLine = shadowDetail
1348:       ? `  ${chalk.red('⚠ Shadows surfaced: ' + shadowDetail)}`
1349:       : `  ${chalk.green('✓ No shadows surfaced this session')}`;
1350: 
1351:     // NPC relationship summary
1352:     const holonDeltas = history.flatMap(r => r.holonDeltas ?? []);
1353:     const relChanges = holonDeltas.filter(d => d.field === 'relationshipStrength');
1354:     const relLine = relChanges.length > 0
1355:       ? `  ${chalk.dim('NPC relationships shifted: ' + relChanges.length + ' encounter' + (relChanges.length > 1 ? 's' : '') + ' with bond changes')}`
1356:       : '';
1357: 
1358:     console.log(`\n  ${chalk.bold('Session Closure')}`);
1359:     console.log(`  ${openingLine}`);
1360:     if (altLine) console.log(altLine);
1361:     console.log(shadowLine);
1362:     if (relLine) console.log(relLine);
1363:     console.log(`\n  ${chalk.dim('The session closes. Each encounter was a mirror — reflecting not who you are, but who you are becoming.')}`);
1364:   }
1365: 
1366:   info('encounters completed', String(completedCount));
1367:   info('total encounters', String(currentSig.totalEncounters));
1368:   info('total sessions', String(sessionEnd.sig.totalSessions));
1369: 
1370:   // Show developmental trajectory (compute fresh CCI from final Significator state)
1371:   console.log('');
1372:   const finalSnapshot = toSnapshot(sessionEnd.sig);
1373:   const finalCCI = computeCCI(finalSnapshot);
1374:   renderCCIDisplay(finalCCI);
1375:   console.log('');
1376:   renderAltitudesChart(currentSig);
1377:   console.log('');
1378:   renderShadows(currentSig);
1379:   renderDrives(currentSig);
1380: 
1381:   if (!JSON_MODE) {
1382:     const bleedThrough = detectBleedThrough(currentSig.theta.lastEncounter, Date.now());
1383:     console.log('');
1384:     console.log(renderLayers(currentSig, bleedThrough));
1385:   }
1386: 
1387:   // Shadow summary
1388:   if (sessionEnd.summary.shadowsSurfaced > 0) {
1389:     info('shadows surfaced', String(sessionEnd.summary.shadowsSurfaced));
1390:     info('shadows resolved', String(sessionEnd.summary.shadowsResolved));
1391:   }
1392: 
1393:   if (VERBOSE) {
1394:     console.log('\nFinal Significator:');
1395:     printSignificator(sessionEnd.sig);
1396:   }
1397: 
1398:   emitEvent('session_ended', {
1399:     encountersCompleted: completedCount,
1400:     totalEncounters: currentSig.totalEncounters,
1401:     totalSessions: sessionEnd.sig.totalSessions,
1402:     shadowsSurfaced: sessionEnd.summary.shadowsSurfaced,
1403:     shadowsResolved: sessionEnd.summary.shadowsResolved,
1404:     finalStage: sessionEnd.sig.currentStage,
1405:   });
