1487: // ── Ollama auto-detect ──────────────────────────────────────────
1488: async function detectOllama(): Promise<{ running: boolean; models: string[] }> {
1489:   try {
1490:     const controller = new AbortController();
1491:     const timeout = setTimeout(() => controller.abort(), 3000);
1492:     const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1493:     clearTimeout(timeout);
1494:     if (!res.ok) return { running: false, models: [] };
1495:     const data = (await res.json()) as { models?: { name: string }[] };
1496:     const models = (data.models ?? []).map(m => m.name.split(':')[0] ?? m.name);
1497:     return { running: true, models: [...new Set(models)] };
1498:   } catch {
1499:     return { running: false, models: [] };
1500:   }
1501: }
