1503: // ── API key verification ────────────────────────────────────────
1504: async function verifyProviderConnection(provider: ProviderInfo, apiKeyVal: string, modelVal: string, baseUrlVal: string): Promise<{ ok: boolean; message: string }> {
1505:   try {
1506:     const controller = new AbortController();
1507:     const timeout = setTimeout(() => controller.abort(), 10_000);
1508: 
1509:     if (provider.id === 'ollama') {
1510:       // Ollama: GET /api/tags
1511:       const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1512:       clearTimeout(timeout);
1513:       if (res.ok) return { ok: true, message: 'Ollama connected' };
1514:       return { ok: false, message: `Ollama responded with ${res.status}` };
1515:     }
1516: 
1517:     if (provider.id === 'anthropic') {
1518:       // Anthropic: POST /v1/messages with minimal payload
1519:       const res = await fetch(`${baseUrlVal}/messages`, {
1520:         method: 'POST',
1521:         headers: {
1522:           'Content-Type': 'application/json',
1523:           'x-api-key': apiKeyVal,
1524:           'anthropic-version': '2023-06-01',
1525:         },
1526:         body: JSON.stringify({
1527:           model: modelVal,
1528:           messages: [{ role: 'user', content: 'ping' }],
1529:           max_tokens: 1,
1530:         }),
1531:         signal: controller.signal,
1532:       });
1533:       clearTimeout(timeout);
1534:       if (res.ok) return { ok: true, message: 'Anthropic connected' };
1535:       if (res.status === 401 || res.status === 403) return { ok: false, message: 'Invalid API key' };
1536:       return { ok: false, message: `Anthropic responded with ${res.status}` };
1537:     }
1538: 
1539:     // OpenAI / Gemini / Custom: GET /models
1540:     const res = await fetch(`${baseUrlVal}/models`, {
1541:       headers: { 'Authorization': `Bearer ${apiKeyVal}` },
1542:       signal: controller.signal,
1543:     });
1544:     clearTimeout(timeout);
1545:     if (res.ok) return { ok: true, message: 'Connected' };
1546:     if (res.status === 401 || res.status === 403) return { ok: false, message: 'Invalid API key' };
1547:     return { ok: false, message: `Endpoint responded with ${res.status}` };
1548:   } catch (err: any) {
1549:     return { ok: false, message: err.name === 'AbortError' ? 'Connection timed out' : 'Connection failed' };
1550:   }
1551: }
