17: // ── ANSI helpers (must be at top for const hoisting) ──────────────────
18: 
19: const C = {
20:   reset: '\x1b[0m', bold: '\x1b[1m', dim: '\x1b[2m',
21:   green: '\x1b[32m', yellow: '\x1b[33m', blue: '\x1b[34m',
22:   magenta: '\x1b[35m', cyan: '\x1b[36m', red: '\x1b[31m',
23: };
