25: // ── Option type with drive metadata ───────────────────────────────────
26: 
27: interface DriveOption {
28:   label: string;
29:   description: string;
30:   drive: 'agency' | 'communion' | 'eros' | 'agape';
31:   polarity: 'sto' | 'sts' | 'neutral';
32:   /** Score multiplier for correctness (1.0 = correct, 0.5 = partial, 0.0 = wrong) */
33:   correctnessScore: number;
34: }
