36: /**
37:  * Shuffle an array in place (Fisher-Yates). Returns the same array.
38:  */
39: function shuffle<T>(arr: T[]): T[] {
40:   for (let i = arr.length - 1; i > 0; i--) {
41:     const j = Math.floor(Math.random() * (i + 1));
42:     [arr[i], arr[j]] = [arr[j]!, arr[i]!];
43:   }
44:   return arr;
45: }
