398: /**
399:  * Render a Hold task: show items to remember, then ask the player to recall.
400:  */
401: export function renderHold(task: AssessmentTask): {
402:   prompt: AskUserQuestionParams;
403:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
404: } {
405:   const diff = getDifficulty(task.parameters.stage as string | undefined);
406:   const itemCount = (task.parameters.items as number) ?? diff.holdItems;
407:   const holdDurationMs = (task.parameters.holdDurationMs as number) ?? diff.holdDurationMs;
408: 
409:   const items = diff.symbolPool.slice(0, itemCount);
410: 
411:   const question = [
412:     `Remember these ${itemCount} symbols:`,
413:     ``,
414:     `  ${items.join('   ')}`,
415:     ``,
416:     `Hold them in your mind for ${Math.round(holdDurationMs / 1000)} seconds.`,
417:     `Now: ${C.bold}List the symbols in order${C.reset}`,
418:   ].join('\n');
419: 
420:   // Options: correct recall, partial, vague, forgot
421:   const options: DriveOption[] = [
422:     { label: `${items.join(' ')}`, description: `I remember: ${items.join(', ')}`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
423:     { label: `${items.slice(0, -1).join(' ')}…`, description: `I remember ${items.length - 1} of them`, drive: 'communion', polarity: 'neutral', correctnessScore: 0.7 },
424:     { label: `Some symbols`, description: 'I recall parts but not all', drive: 'eros', polarity: 'neutral', correctnessScore: 0.4 },
425:     { label: `Slipped away`, description: 'The symbols faded from memory', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
426:   ];
427:   shuffle(options);
428: 
429:   return {
430:     prompt: {
431:       questions: [{
432:         question,
433:         header: 'Attentional Hold',
434:         options: options.map(o => ({ label: o.label, description: o.description })),
435:         allowWriteIn: true,
436:         multiSelect: false,
437:       }],
438:     },
439:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
440:       const durationMs = endTimeMs - startTimeMs;
441: 
442:       const answerLower = answer.toLowerCase();
443:       const matched = items.filter(item => answerLower.includes(item));
444:       const accuracy = matched.length / items.length;
445: 
446:       const responseTime = holdDurationMs > 0 ? Math.min(1, holdDurationMs / (holdDurationMs * 2)) : 0.7;
447:       // Match against full label to handle shuffled options correctly
448:       const matchedOpt = options.find(o => answer.toLowerCase().includes(o.label.toLowerCase()));
449: 
450:       return {
451:         taskId: task.id,
452:         timestamp: startTimeMs,
453:         dimensions: { accuracy, response_time: responseTime, consistency: accuracy },
454:         rawResponse: {
455:           items, matched, answer,
456:           matchedDrive: matchedOpt?.drive ?? null,
457:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
458:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
459:         },
460:         durationMs,
461:       };
462:     },
463:   };
464: }
