558:   const scenario = scenarios[Math.floor(Math.random() * scenarios.length)]!;
559:   const correctOpt: DriveOption = { label: scenario.emotion, description: 'Identify this emotion', drive: 'eros', polarity: 'neutral', correctnessScore: 1.0 };
560:   const wrongOpts: DriveOption[] = scenario.wrong.map((w, i) => ({
561:     label: w,
562:     description: 'A different emotional state',
563:     drive: i === 0 ? 'agency' : i === 1 ? 'communion' : 'agape',
564:     polarity: 'neutral',
565:     correctnessScore: 0.2,
566:   }));
567:   const options = shuffle([correctOpt, ...wrongOpts]);
568: 
569:   const question = [
570:     `Read this scenario and identify the PRIMARY emotion:`,
571:     ``,
572:     `  "${scenario.text}"`,
573:     ``,
574:     `${C.bold}What emotion does the person feel?${C.reset}`,
575:   ].join('\n');
576: 
577:   return {
578:     prompt: {
579:       questions: [{
580:         question,
581:         header: 'Emotional Literacy',
582:         options: options.map(o => ({ label: o.label, description: o.description })),
583:         allowWriteIn: true,
584:         multiSelect: false,
585:       }],
586:     },
587:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
588:       const durationMs = endTimeMs - startTimeMs;
589:       const isCorrect = answer.toLowerCase().includes(scenario.emotion.toLowerCase());
590: 
591:       const accuracy = isCorrect ? 0.9 : 0.3;
592:       const responseTime = durationMs < 10000 ? 0.8 : durationMs < 30000 ? 0.6 : 0.4;
593: 
594:       const matchedOpt = options.find(o => answer.toLowerCase().includes(o.label.toLowerCase()));
595: 
596:       return {
597:         taskId: task.id,
598:         timestamp: startTimeMs,
599:         dimensions: {
600:           accuracy,
601:           response_time: responseTime,
602:           depth: isCorrect ? 0.7 : 0.3,
603:         },
604:         rawResponse: {
605:           scenario: scenario.text, playerEmotion: answer, expectedEmotion: scenario.emotion, isCorrect,
606:           matchedDrive: matchedOpt?.drive ?? null,
607:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
608:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
609:         },
610:         durationMs,
611:       };
612:     },
613:   };
614: }
